INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62354092', 62354092, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'PUSAT PELAPORAN DAN ANALISIS TRANSAKSI KEUANGAN', 'Pengadaan Layanan Intranet Pertama PPATK T.A. 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 700000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Dalam rangka menjaga layanan hot backup DC-DRC dan memastikan sistem dan perangkat di DRC selalu berjalan dengan baik dan lancar', '1. Spesifikasi Teknis Layanan Intranet 1st Link Metro Ethernet 1000 Mbps: a. Jenis Layanan • Metro ethernet layer 2 (data link / switching) • Originating : Kantor pusat PPATK (Jl. Ir. H. Juanda No. 35, DKI Jakarta) • Terminating : Pusdiklat PPATK (Jl. Raya Tapos No. 82, Kota Depok) • Atau sebaliknya • Bandwidth sebesar 1000 Mbps dengan rasio CIR 1:1; b. Jaringan (backbone) fiber optic yang digunakan dalam layanan ini merupakan milik sendiri (tidak menggunakan jaringan fiber optic milik perusahaan lain); c. Interface dan tipe konektor yang terhubung ke perangkat CE (customer edge) PPATK adalah 10G SFP+; d. Infrastruktur yang digunakan mampu memenuhi permintaan penambahan (upgrade) permanen kapasitas bandwidth oleh PPATK; e. Sanggup menyediakan kenaikan bandwidth temporer (bandwidth-on-demand) minimal 200% dari bandwidth yang sedang disewa sesuai dengan prosedur yang berlaku di ISP dan menyediakan teknisi on-site ketika bandwidth-on demand berlangsung; f. Perangkat aktif milik ISP yang dipasang di PPATK dan digunakan untuk layanan ini harus memiliki redundant power supply; g. Service Level Agreement (SLA) • Uptime ≥ 99,9% per bulan (dari jumlah bandwidth yang disewa) • Response time (corrective maintenance) max 1 jam setelah laporan h. Dukungan Teknis • NOC 24x7 dengan kontak eskalasi • Kunjungan technical support saat dibutuhkan sepanjang 24x7 • Layanan pengawasan gangguan secara dini (preventive support); i. Pemantauan • Portal pemantauan online 24x7 untuk pengguna j. Laporan Rutin • Wajib disampaikan secara bulanan melalui email • Berisi setidaknya: i. Statistik dan/atau grafik penggunaan bandwidth ii. Laporan jumlah dan persentase uptime dan downtime iii. Log insiden dan penanganan iv. History gangguan (planned/unplanned) k. Sanggup menyediakan kenaikan bandwidth temporer (bandwidth-on-demand) minimal 200% dari bandwidth yang sedang disewa sesuai dengan prosedur yang berlaku di ISP dan menyediakan teknisi on-site ketika bandwidth-on demand berlangsung.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 411539);
