INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62357316', 62357316, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA TANJUNG KARANG01', 'Jasa Satpam', 'Jasa Lainnya', 'E-Purchasing', 'Lampung, Bandar Lampung (Kota)', 185484000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '4 Orang 13 Bulan', '1. Menjaga keamanan dan ketertiban di lingkungan kantor. 2. Melaksanakan patroli rutin di area dalam dan luar gedung sesuai jadwal. 3. Mengatur dan mengawasi keluar masuk pegawai, tamu, dan masyarakat. 4. Melakukan pemeriksaan identitas tamu sesuai prosedur yang berlaku. 5. Memberikan informasi awal serta mengarahkan tamu ke unit atau bagian yang dituju. 6. Menjaga dan mengamankan aset, sarana, dan prasarana kantor. 7. Mengawasi kondisi gedung, pintu, jendela, dan fasilitas kantor agar tetap aman. 8. Menangani dan mengantisipasi gangguan keamanan dan ketertiban secara persuasif.', '1. Pendidikan minimal SMA/sederajat. 2. Memiliki sertifikat pelatihan Satpam yang masih berlaku. 3. Sehat jasmani dan rohani serta berpenampilan rapi dan sopan. 4. Usia sesuai ketentuan yang berlaku. 5. Memiliki tinggi dan berat badan proporsional. 6. Mampu berkomunikasi dengan baik dan santun. 7. Memiliki sikap disiplin, jujur, tegas, dan bertanggung jawab. 8. Mampu bekerja secara mandiri maupun dalam tim.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 413483);
