INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62357502', 62357502, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BADAN PERENCANAAN PEMBANGUNAN DAERAH', 'Penyediaan Tenaga Ahli Placemaking 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 92400000, 'December 2025', 'APBD', 1, 1, '1 Paket', 'a. Melakukan pendampingan dan dokumentasi rapat teknis pemerintahan dan pengkajian peraturan yang dilaksanakan oleh Bidang Perekonomian urusan placemaking, b. Membantu identifikasi isu dan kendala pada pelaksanaan kegiatan Bidang Perekonomian terkait pembangunan daerah sektor placemaking, c. Memberikan saran dan pertimbangan terhadap suatu gagasan dan konsep sesuai ruang lingkupnya; d. Membantu Bidang Perekonomian dalam menyusun suatu draft telaahan, analisis dan kajian; e. Melakukan konsultasi, koordinasi dan pertemuan/diskusi internal dengan Perangkat Daerah/Kementerian/Lembaga/Institusi sesuai kebutuhan pengumpulan bahan materi; f. Melaksanakan dan menyelesaikan pekerjaan sesuai dengan jadwal pelaksanaan pekerjaan yang telah ditetapkan; g. Melaporkan dan mempresentasikan data dan informasi terkait issue/permasalahan kepada Kepala Bidang Perekonomian secara periodik; h. Menghadiri dan melaporkan hasil kegiatan; i. Membantu penyusunan rencana dan konsep implementasi dalam bentuk rekomendasi program atau kegiatan; dan j. Tugas tambahan lainnya yang disesuaikan dengan kebutuhan Bidang Perekonomian.', 'a. Berlatar belakang pendidikan minimal magister (S2) pada jurusan/program studi Perencanaan Wilayah dan Kota/Planologi, Arsitektur, Arsitektur Lanskap, atau Desain Kota/Urban Design; b. Memiliki pengalaman bekerja minimal 9 (sembilan) tahun di Instansi Pemerintah Daerah, Pemerintah Pusat, Lembaga Nasional atau Instansi lainnya; c. Mempunyai pengalaman dalam membuat analisis kebijakan dan pengolahan data terkait perencanaan dan pembangunan; d. Memiliki Sertifikat Keahlian (SKA) yang diterbitkan oleh Lembaga Pengembangan Jasa Konstruksi (LPJK) sebagai bukti kompetensi dan kapabilitas profesi tenaga ahli di bidang jasa non konstruksi; e. Mempunyai pengalaman dalam penyusunan dokumen perencanaan Pemerintah Daerah dan/atau policy brief/policy paper; f. Mempunyai pengalaman dalam analisis lintas sektor; g. Dapat mengoperasikan Microsoft Office dan Google Workspace dengan sangat baik; h. Dapat mengoperasikan program pemetaan, pemodelan, dan penyajian data visual seperti ArcGIS/QGIS; i. Memiliki peralatan kerja sendiri yang diperlukan untuk menjalankan tugas akan menjadi nilai tambah (contoh: Laptop); dan j. Mahir dalam berbahasa inggris (minimal skor TOEFL 500).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 414028);
