INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62315055', 62315055, 'analyze_legacy', 'Kementerian Agama', 'central', 'INSTITUT AGAMA KRISTEN NEGERI TARUTUNG 552755', 'Pengadaan Jasa Cleaning Service', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Utara, Tapanuli Utara (Kab.)', 1374334000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Belanja Jasa Lainnya', 'Spesifikasi pekerjaan cleaning service kampus mencakup tugas harian (menyapu, mengepel, membuang sampah, membersihkan toilet, kaca, dan area umum seperti koridor/lobi), tugas berkala (pembersihan mendalam mingguan/bulanan), serta penanganan khusus area seperti ruang dosen, laboratorium, kantin, dan menjaga kebersihan sarana prasarana utama kampus dengan menerapkan standar kebersihan tinggi, terutama di area publik, untuk menciptakan lingkungan belajar nyaman, didukung keahlian penggunaan alat dan bahan kimia serta etika kerja profesional. Tanggung Jawab Utama Kebersihan Ruangan: Menyapu, mengepel, membersihkan debu di meja, kursi, lemari, komputer, jendela, dan langit-langit di ruang kelas, kantor, lab, dll.. Kebersihan Toilet: Membersihkan lantai, dinding, kloset, wastafel, cermin, memastikan ketersediaan tisu dan sabun setiap saat. Pengelolaan Sampah: Membuang sampah domestik dan medis secara rutin, membersihkan tempat sampah. Area Publik: Menjaga kebersihan lobi, koridor, tangga, selasar, dan tempat sampah rokok. Pembersihan Berkala: Membersihkan kaca (mingguan), area pantry, dan peralatan makan. Lingkup Area Kerja Gedung & Ruangan: Kelas, ruang dosen, ruang pimpinan, ruang rapat, perpustakaan, lab, pantry, toilet, lobi, koridor, tangga, balkon. Area Luar (Teras & Halaman): Menyapu halaman, membersihkan teras dan selasar luar.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 415706);
