INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62315053', 62315053, 'analyze_legacy', 'Kementerian Agama', 'central', 'INSTITUT AGAMA KRISTEN NEGERI TARUTUNG 552755', 'Pengadaan Jasa Supir/Driver', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Utara, Tapanuli Utara (Kab.)', 288670000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Belanja Jasa Lainnya;', 'Spesifikasi jasa supir kampus mencakup SIM valid, rekam jejak mengemudi bersih, kemampuan teknis baik (defensive driving), sikap profesional & ramah, disiplin waktu, serta pemahaman rute kampus untuk memastikan keamanan, kenyamanan, dan efisiensi mobilitas civitas akademika, seringkali melibatkan pelatihan tambahan & background check. Kualifikasi Utama (Hard Skills & Legalitas) Surat Izin Mengemudi (SIM): Memiliki SIM A/B1 yang sesuai jenis kendaraan (mobil/bus kampus) dan masih berlaku. Rekam Jejak Mengemudi Bersih: Bebas dari pelanggaran lalu lintas berat atau kecelakaan fatal, bisa dibuktikan melalui pemeriksaan latar belakang. Sertifikasi & Pelatihan: Mengikuti pelatihan Defensive Driving (mengemudi defensif) dan etika pelayanan pelanggan akan sangat meningkatkan kualitas. Kemampuan Teknis: Terampil mengemudi di berbagai kondisi jalan, termasuk area kampus yang mungkin ramai atau sempit, serta peduli pada keamanan kendaraan. Kualifikasi Pendukung (Soft Skills & Attitude) Sikap Profesional & Ramah: Sopan santun, berdedikasi, serta mampu membangun hubungan baik dengan mahasiswa, dosen, dan staf. Disiplin & Tanggung Jawab: Tepat waktu dalam jadwal antar-jemput, bertanggung jawab atas keselamatan penumpang dan kendaraan. Berwawasan & Peduli: Memiliki pengetahuan dasar tentang rute kampus, lokasi penting, serta proaktif menjaga kenyamanan penumpang. Integritas & Kepercayaan: Memiliki kesadaran tinggi akan profesi dan amanah yang diberikan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 416453);
