INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62362013', 62362013, 'analyze_legacy', 'Kota Blitar', 'kabkota', 'Dinas Komunikasi, Informatika dan Statistik', 'Belanja Internet Dedicated Utama', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Blitar (Kota)', 1000000000, 'December 2025', 'APBD', 0, 1, '1', 'Internet dedicated sebesar 1 Gbps (1:1)', 'RUANG LINGKUP PEKERJAAN : 1. Penyediaan Bandwidth Internet Dedicated a. Bandwidth dedicated sebesar 1 Gbps (1:1) upload dan download; b. Koneksi bersifat dedicated dan tidak oversubscribe; c. Memberikan jalur koneksi khusus dari POP (Point Of Presence) ke MMR (Meet Me Room) Pemerintah Kota Blitar; d. Menjaga kualitas koneksi internet dedicated dengan rasio 1:1 antara upload dan download; e. Media koneksi menggunakan infrastruktur yang andal dan terproteksi. 2. Layanan IP Transit a. Penyediaan IP Transit (IPv4/IPv6 sesuai kebutuhan); b. Pengelolaan routing dan konektivitas internet global; c. Dukungan optimasi jalur trafik. 3. Managed Service Sistem Jaringan dan Network Security a. Pengelolaan dan pemeliharaan perangkat jaringan inti meliputi server, seluruh perangkat daerah, jaringan backbone fiber optic dan cctv; b. Konfigurasi dan pemeliharaan perangkat router, switch juniper, firewall, access control, dan kebijakan keamanan jaringan; c. Penanganan insiden keamanan jaringan. 4. Managed Service Technical On Site (TOS) a. Dukungan teknis on site sesuai kebutuhan dan SLA; b. Troubleshooting dan pemulihan gangguan jaringan; c. Koordinasi teknis dengan pengelola SPBE Pemerintah Kota Blitar. 5. Monitoring dan Pelaporan a. Sistem monitoring bandwidth usage dan availability; b. Akses dashboard monitoring; c. Laporan bulanan kinerja layanan dan penggunaan bandwidth.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 418751);
